<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,TutorGroup,LearningTask,AccountLifecycleProposal as Proposal,AccountLifecycleState as State};
use App\Support\{AccountLifecycle as L,AccountAccess,ReviewedImports};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Hash,Password,Mail,Http,Crypt};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class AccountLifecycleTest extends TestCase {
 use LazilyRefreshDatabase;
 private function f():array {$admin=User::factory()->create(['role'=>'admin']);$ceo=User::factory()->create(['role'=>'ceo']);$target=User::factory()->create(['role'=>'tutor','password'=>'Original-test-passphrase-43']);return compact('admin','ceo','target');}
 private function make(array $f,string $action='Archive',?string $token=null):Proposal {$s=L::source($f['target']->fresh());return L::prepare($f['admin'],1,$f['target'],$token??(string)Str::uuid(),$action,$s['hash'],today()->addDays(14)->toDateString(),'Fictional reviewed retention ref','Fictional continuity handover ref','Fictional checked account decision');}
 private function approved(array $f,string $action='Archive'):Proposal {$p=$this->make($f,$action);L::review($f['ceo'],1,$p,1,true,'Independent checked identity');return $p->refresh();}
 private function applied(array $f,string $action='Archive'):Proposal {$p=$this->approved($f,$action);L::apply($f['admin'],1,$p,2);return $p->refresh();}
 private function reject(callable $fn):void {try{$fn();$this->fail('Expected checked rejection');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 #[\PHPUnit\Framework\Attributes\TestWith(['Archive','Archived'])] #[\PHPUnit\Framework\Attributes\TestWith(['Restrict','Restricted'])]
 public function test_reviewed_disable_retains_role_and_evidence(string $action,string $state):void {$f=$this->f();$a=Apprentice::factory()->create(['tutor_id'=>$f['target']->id]);$t=LearningTask::factory()->create(['apprentice_id'=>$a->id]);$before=$t->fresh()->getAttributes();$this->applied($f,$action);$this->assertFalse($f['target']->fresh()->active);$this->assertSame('tutor',$f['target']->fresh()->role);$this->assertSame($state,State::find($f['target']->id)->status);$this->assertSame($f['target']->id,$a->fresh()->tutor_id);$this->assertSame($before,$t->fresh()->getAttributes());}
 public function test_disable_invalidates_known_password_sessions_onboarding_and_reset_tokens():void {$f=$this->f();Password::broker()->createToken($f['target']);DB::table('account_onboarding_tokens')->insert(['user_id'=>$f['target']->id,'purpose'=>'invite','token_hash'=>str_repeat('a',64),'auth_version'=>1,'created_at'=>now(),'expires_at'=>now()->addDay()]);DB::table('sessions')->insert(['id'=>'fictional-session','user_id'=>$f['target']->id,'payload'=>'fictional','last_activity'=>time()]);$this->applied($f);$this->assertFalse(Hash::check('Original-test-passphrase-43',$f['target']->fresh()->password));$this->assertSame(2,$f['target']->fresh()->auth_version);$this->assertDatabaseCount('account_onboarding_tokens',0);$this->assertDatabaseCount('password_reset_tokens',0);$this->assertDatabaseCount('sessions',0);}
 public function test_restore_requires_new_review_and_does_not_restore_old_credentials():void {$f=$this->f();$this->applied($f);$f['target']->refresh();$this->applied($f,'Restore');$this->assertTrue($f['target']->fresh()->active);$this->assertFalse(L::blocked($f['target']->fresh()));$this->assertFalse(Hash::check('Original-test-passphrase-43',$f['target']->fresh()->password));$this->assertSame(3,$f['target']->fresh()->auth_version);}
 public function test_no_change_occurs_before_review_and_apply():void {$f=$this->f();$p=$this->make($f);$this->assertTrue($f['target']->fresh()->active);$this->reject(fn()=>L::apply($f['admin'],1,$p,1));$this->assertDatabaseCount('account_lifecycle_states',0);}
 public function test_exact_prepare_replay_returns_one_proposal():void {$f=$this->f();$token=(string)Str::uuid();$a=$this->make($f,'Archive',$token);$b=$this->make($f,'Archive',$token);$this->assertSame($a->id,$b->id);$this->assertDatabaseCount('account_lifecycle_proposals',1);}
 public function test_different_action_cannot_reuse_request_token():void {$f=$this->f();$token=(string)Str::uuid();$this->make($f,'Archive',$token);$this->reject(fn()=>$this->make($f,'Restrict',$token));}
 public function test_admin_cannot_review_own_proposal():void {$f=$this->f();$p=$this->make($f);$this->actingAs($f['admin'])->post('/account-operations/proposals/'.$p->id.'/review',['version'=>1,'accept'=>1,'reference'=>'Self approval rejected','confirmed'=>1])->assertForbidden();}
 public function test_admin_cannot_claim_ceo_override():void {$f=$this->f();$p=$this->make($f);$this->actingAs($f['admin'])->post('/account-operations/proposals/'.$p->id.'/review',['version'=>1,'accept'=>1,'override'=>1,'reference'=>'Forged CEO override','confirmed'=>1])->assertForbidden();}
 public function test_ceo_can_explicitly_override_own_subordinate_account_proposal():void {$f=$this->f();$f['admin']=$f['ceo'];$p=$this->make($f,'Restrict');L::review($f['ceo'],1,$p,1,true,'Explicit CEO continuity override',true);L::apply($f['ceo'],1,$p->refresh(),2);$this->assertFalse($f['target']->fresh()->active);$this->assertTrue($p->fresh()->approval['ceo_override']);}
 public function test_ceo_override_can_restore_subordinate_when_ceo_is_only_operator():void {$f=$this->f();$target=$f['admin'];$f['admin']=$f['ceo'];$f['target']=$target;foreach(['Restrict','Restore']as$action){$p=$this->make($f,$action);L::review($f['ceo'],1,$p,1,true,'Explicit CEO recovery override',true);L::apply($f['ceo'],1,$p->refresh(),2);$f['target']->refresh();}$this->assertTrue($target->fresh()->active);$this->assertTrue($f['ceo']->fresh()->active);}
 public function test_self_or_ceo_target_cannot_be_disabled():void {$f=$this->f();foreach([$f['admin'],$f['ceo']]as$t){$this->actingAs($f['admin'])->post('/account-operations/user/'.$t->id.'/prepare',['request_token'=>(string)Str::uuid(),'action'=>'Archive','source_hash'=>L::source($t)['hash'],'review_on'=>today()->addDay()->toDateString(),'retention'=>'Retention checked','handover'=>'Handover checked','reason'=>'Not permitted target','confirmed'=>1])->assertForbidden();}$this->assertTrue($f['ceo']->fresh()->active);}
 #[\PHPUnit\Framework\Attributes\TestWith(['tutor'])] #[\PHPUnit\Framework\Attributes\TestWith(['manager'])] #[\PHPUnit\Framework\Attributes\TestWith(['apprentice'])] #[\PHPUnit\Framework\Attributes\TestWith(['employer'])]
 public function test_non_identity_administrators_cannot_read_or_write_account_operations(string $role):void {$f=$this->f();$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/account-operations')->assertForbidden();$this->post('/account-operations/user/'.$f['target']->id.'/prepare',[])->assertForbidden();}
 public function test_current_source_and_assignment_changes_invalidate_approval():void {$f=$this->f();$p=$this->approved($f);Apprentice::factory()->create(['tutor_id'=>$f['target']->id]);$this->reject(fn()=>L::apply($f['admin'],1,$p,2));$this->assertTrue($f['target']->fresh()->active);}
 public function test_missing_continuity_for_staff_is_rejected_even_without_apprentices():void {$f=$this->f();$this->reject(fn()=>L::prepare($f['admin'],1,$f['target'],(string)Str::uuid(),'Archive',L::source($f['target'])['hash'],today()->addDay()->toDateString(),'Retention reference','','Reason reference'));}
 public function test_preparer_or_reviewer_authority_change_holds_apply():void {$f=$this->f();$p=$this->approved($f);$f['ceo']->forceFill(['auth_version'=>2])->save();$this->reject(fn()=>L::apply($f['admin'],1,$p,2));$this->assertTrue($f['target']->fresh()->active);}
 public function test_preparer_revocation_holds_independent_review():void {$f=$this->f();$p=$this->make($f);$f['admin']->forceFill(['active'=>false])->save();$this->reject(fn()=>L::review($f['ceo'],1,$p,1,true,'Independent check'));}
 public function test_rejection_is_terminal_for_apply():void {$f=$this->f();$p=$this->make($f);L::review($f['ceo'],1,$p,1,false,'Not enough continuity evidence');$this->reject(fn()=>L::apply($f['admin'],1,$p->refresh(),2));}
 public function test_stale_record_version_holds_review():void {$f=$this->f();$p=$this->make($f);$this->reject(fn()=>L::review($f['ceo'],1,$p,99,true,'Stale review'));}
 public function test_managed_restriction_is_sticky_after_legacy_active_flag_edit():void {$f=$this->f();$this->applied($f);$f['target']->forceFill(['active'=>true])->save();$this->assertTrue(L::blocked($f['target']->fresh()));$this->actingAs($f['target']->fresh())->get('/account/password')->assertForbidden();$this->assertNull(AccountAccess::eligible($f['target']->email));}
 public function test_directory_cannot_bypass_managed_restore():void {$f=$this->f();$this->applied($f);$t=$f['target']->fresh();$this->actingAs($f['admin'])->put('/directories/staff/'.$t->id,['name'=>$t->name,'email'=>$t->email,'role'=>'tutor','active'=>1,'record_version'=>$t->record_version])->assertSessionHasErrors('active');$this->assertFalse($t->fresh()->active);}
 public function test_corrupt_state_holds_even_with_active_flag_true():void {$f=$this->f();$this->applied($f);$f['target']->forceFill(['active'=>true])->save();DB::table('account_lifecycle_states')->where('user_id',$f['target']->id)->update(['status'=>'Active']);$this->assertTrue(L::blocked($f['target']->fresh()));}
 public function test_apply_audit_failure_rolls_back_credentials_sessions_and_state():void {$f=$this->f();$p=$this->approved($f);$before=$f['target']->fresh()->getAttributes();AuditFault::install('account_apply_fault','portal_operations_events','Fictional failure','account_applied');try{L::apply($f['admin'],1,$p,2);$this->fail('Expected failure');}catch(\Illuminate\Database\QueryException){$this->assertSame($before,$f['target']->fresh()->getAttributes());$this->assertDatabaseCount('account_lifecycle_states',0);$this->assertSame('Approved',$p->fresh()->state);}}
 public function test_proposal_and_event_payloads_are_encrypted():void {$f=$this->f();$this->make($f);$this->assertStringNotContainsString('Fictional reviewed retention',DB::table('account_lifecycle_proposals')->value('details'));$this->assertStringNotContainsString('source_hash',DB::table('portal_operations_events')->value('payload'));}
 public function test_retention_review_changes_neither_login_nor_evidence():void {$f=$this->f();$this->applied($f);$before=$f['target']->fresh()->getAttributes();L::retain($f['admin'],1,$f['target'],1,today()->addDays(30)->toDateString(),'Updated reviewed retention ref','Human retention review');$this->assertSame($before,$f['target']->fresh()->getAttributes());$this->assertSame(2,State::find($f['target']->id)->version);$this->assertTrue(L::blocked($f['target']->fresh()));}
 public function test_retention_stale_version_and_past_date_rejected():void {$f=$this->f();$this->applied($f);$this->reject(fn()=>L::retain($f['admin'],1,$f['target'],99,today()->addDay()->toDateString(),'Checked ref','Checked reason'));$this->reject(fn()=>L::retain($f['admin'],1,$f['target'],1,today()->subDay()->toDateString(),'Checked ref','Checked reason'));}
 public function test_ledger_is_encrypted_and_inspection_is_read_only():void {$f=$this->f();$this->applied($f);$sealed=L::ledger($f['admin']);$this->assertStringNotContainsString($f['target']->email,$sealed);$before=$f['target']->fresh()->getAttributes();$report=L::inspectLedger($f['admin'],$sealed);$this->assertFalse($report['writes_performed']);$this->assertTrue($report['rows'][0]['identity_matches']);$this->assertTrue($report['rows'][0]['login_still_blocked']);$this->assertSame($before,$f['target']->fresh()->getAttributes());}
 public function test_modified_or_wrong_key_ledger_is_rejected():void {$f=$this->f();$this->applied($f);$this->reject(fn()=>L::inspectLedger($f['admin'],L::ledger($f['admin']).'broken'));}
 public function test_ledger_does_not_guess_identity_by_name_after_email_change():void {$f=$this->f();$this->applied($f);$sealed=L::ledger($f['admin']);$f['target']->forceFill(['email'=>'changed@example.test'])->save();$report=L::inspectLedger($f['admin'],$sealed);$this->assertFalse($report['rows'][0]['identity_matches']);$this->assertFalse($report['rows'][0]['login_still_blocked']);}
 public function test_login_restore_and_retention_views_render_private_headers():void {$f=$this->f();$p=$this->make($f);$this->actingAs($f['admin'])->get('/account-operations?user_id='.$f['target']->id)->assertOk()->assertHeader('Referrer-Policy','no-referrer');$this->actingAs($f['ceo'])->get('/account-operations/proposals/'.$p->id)->assertOk()->assertSee('Independent review');}
 public function test_no_notifications_or_role_changes_are_made_by_account_operations():void {Mail::fake();Http::preventStrayRequests();$f=$this->f();$this->applied($f);$this->assertSame('tutor',$f['target']->fresh()->role);Mail::assertNothingSent();Http::assertNothingSent();}
 private function privacyCase(array $f):\App\Models\PortalPrivacyCase {$n=\App\Support\PortalPrivacy::draft($f['admin'],1,'fixture43',str_repeat('Fictional privacy text for workflow verification. ',8),'privacy@example.test',array_fill_keys(\App\Support\PortalPrivacy::CHECKS,'Fictional verified reference'));\App\Support\PortalPrivacy::publish($f['ceo'],1,$n,\App\Models\PortalPrivacyState::find(1)->revision);$c=\App\Support\PortalPrivacy::concern($f['target'],1,$n->id,$n->body_hash,(string)Str::uuid(),'Fictional account review concern');\App\Support\PortalPrivacy::decide($f['admin'],1,$c,1,'Archive-review',null,'Reviewed request for separate account action');return $c->refresh();}
 public function test_privacy_account_review_links_to_actual_archive_without_resolving_concern():void {$f=$this->f();$c=$this->privacyCase($f);$source=L::source($f['target']->fresh(),$c->id);$p=L::prepare($f['admin'],1,$f['target'],(string)Str::uuid(),'Archive',$source['hash'],today()->addDays(14)->toDateString(),'Checked retention reference','Checked continuity reference','Reviewed user access request',$c->id);L::review($f['ceo'],1,$p,1,true,'Independent account review');L::apply($f['admin'],1,$p->refresh(),2);$this->assertFalse($f['target']->fresh()->active);$this->assertSame('Archive-review',$c->fresh()->state);$this->assertDatabaseCount('portal_privacy_acknowledgements',0);$this->get('/privacy-information')->assertOk();}
 public function test_managed_restore_does_not_clear_prior_privacy_concern():void {$f=$this->f();$c=$this->privacyCase($f);$this->applied($f);$f['target']->refresh();$this->applied($f,'Restore');$this->actingAs($f['target']->fresh())->get('/account/password')->assertRedirect('/privacy');$this->assertSame('Archive-review',$c->fresh()->state);}

}
